(()=>{const old=navigate;navigate=function(v){if(v==='glossary'){SSCommon.open('glossary');return}return old(v)};const renderOld=render;render=function(){renderOld();document.querySelector('#nav [data-view="glossary"]')?.remove();document.querySelectorAll('#main details').forEach(d=>{if(/教材依據|模型邊界/.test(d.querySelector('summary')?.textContent||'')){const b=document.createElement('button');b.className='secondary';b.dataset.common='sources';b.textContent='教材依據與使用限制';d.replaceWith(b)}});if(SSLocale.get()!=='zh-TW'){const n=document.createElement('p');n.className='language-notice';n.textContent='Learn目前提供繁體中文完整課程。其他語言教材尚未完成；你的Train語言偏好仍會保留。';document.getElementById('main').prepend(n)}if(['module','lesson'].includes(S.view)){const m=S.view==='lesson'?L[S.lesson].m:S.module,e=document.createElement('section');e.className='surface-card';e.innerHTML=`<h2>把理解帶進練習</h2><p>相關模式不等於本課專屬題庫，請連同資料來源閱讀。</p><a class="link-button" href="training.html?mode=${m>=6?'ALL_STREET':m===5?'FACING_3BET':'RFI'}">前往相關訓練 →</a>`;document.getElementById('main').append(e)}};if(S.view==='glossary')S.view='welcome';const p=new URLSearchParams(location.search),m=Number(p.get('module'));if(p.has('module')&&Number.isInteger(m)&&m>=0&&m<M.length)openModule(m);else render();document.addEventListener('sslocale:change',render);document.addEventListener('DOMContentLoaded',()=>{const nav=document.getElementById('nav'),menu=document.getElementById('menu'),anchor=document.createElement('span');anchor.hidden=true;nav.before(anchor);const d=document.createElement('dialog');d.id='course-drawer';d.className='course-drawer';d.setAttribute('aria-labelledby','course-title');d.innerHTML='<div class="dialog-panel"><div class="dialog-head"><h2 id="course-title">課程導覽</h2><button class="secondary">關閉</button></div><div class="dialog-body"></div></div>';document.body.append(d);d.querySelector('button').onclick=()=>d.close();const mq=matchMedia('(max-width:680px)');function layout(){if(mq.matches)d.querySelector('.dialog-body').append(nav);else{if(d.open)d.close();anchor.before(nav)}}layout();mq.addEventListener('change',layout);menu.setAttribute('aria-controls',d.id);menu.setAttribute('aria-haspopup','dialog');menu.setAttribute('aria-expanded','false');menu.onclick=()=>{if(!mq.matches)return;if(d.open)d.close();else{d.showModal();menu.setAttribute('aria-expanded','true')}};d.addEventListener('close',()=>{menu.setAttribute('aria-expanded','false');if(mq.matches)menu.focus({preventScroll:true})});d.addEventListener('click',e=>{if(e.target.closest('.navitem'))d.close()})})})();